import { listTools, callTool } from './server.mjs';

function check(name, fn) {
  try { fn(); console.log('PASS:', name); }
  catch (e) { console.log('FAIL:', name, '-', e.message); process.exitCode = 1; }
}

// additionalProperties:false present
const [t] = await listTools();
check('additionalProperties:false', () => {
  if (t.inputSchema.additionalProperties !== false) throw new Error('missing');
});

// division by zero
check('div by zero throws', async () => {
  try { await callTool('calculate', { a: 1, b: 0, operation: 'divide' }); throw new Error('should have thrown'); }
  catch (e) { if (!/zero/i.test(e.message)) throw e; }
});

// missing field
check('missing field throws', async () => {
  try { await callTool('calculate', { a: 1, operation: 'add' }); throw new Error('should have thrown'); }
  catch (e) {}
});

// extra field
check('extra field throws', async () => {
  try { await callTool('calculate', { a: 1, b: 2, operation: 'add', c: 3 }); throw new Error('should have thrown'); }
  catch (e) {}
});

// unsupported operation
check('unsupported op throws', async () => {
  try { await callTool('calculate', { a: 1, b: 2, operation: 'modulo' }); throw new Error('should have thrown'); }
  catch (e) {}
});

// unknown tool
check('unknown tool throws', async () => {
  try { await callTool('frobnicate', {}); throw new Error('should have thrown'); }
  catch (e) {}
});

// results
check('subtract', async () => {
  const r = await callTool('calculate', { a: 5, b: 2, operation: 'subtract' });
  if (!/3/.test(r.content[0].text)) throw new Error('bad result');
});
check('multiply', async () => {
  const r = await callTool('calculate', { a: 4, b: 3, operation: 'multiply' });
  if (!/12/.test(r.content[0].text)) throw new Error('bad result');
});
check('divide', async () => {
  const r = await callTool('calculate', { a: 6, b: 2, operation: 'divide' });
  if (!/3/.test(r.content[0].text)) throw new Error('bad result');
});
